import{contactNetwork,selectedCohort,doseData,candidateData}from './medicine-models.js?v=20261023-physicscomplete01';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const txt=(x,y,t,size=22)=>`<text x="${x}" y="${y}" text-anchor="middle" fill="#f5eee5" font-size="${size}">${esc(t)}</text>`;
const frame=(body,aria)=>`<svg class="infection-diagram medicine-diagram" viewBox="0 0 560 420" role="img" aria-label="${esc(aria)}">${body}</svg>`;
export function networkFigure(w={}){let n=contactNetwork(w.coverage??0,w.steps??0),pos=i=>[70+i%5*105,80+Math.floor(i/5)*80],body='';for(let[a,b]of n.edges){let[x,y]=pos(a),[u,v]=pos(b);body+=`<path d="M${x} ${y}L${u} ${v}" stroke="#78969a" stroke-width="2"/>`;}for(let i=0;i<20;i++){let[x,y]=pos(i),p=n.protectedNodes.includes(i),infect=n.infected.includes(i);body+=`<circle cx="${x}" cy="${y}" r="22" fill="${p?'#a9c8b9':infect?'#e4a08b':'#b8c9ce'}" ${p?'stroke="#f6dbab" stroke-width="6"':''}/>`+txt(x,y+6,(p?'P':infect?'I':'S')+i,16);}body+=txt(280,385,'P protected · I infected · S susceptible',20);return frame(body,'Fixed20-person network. '+n.infected.length+' infected including seed; '+n.protectedNodes.length+' protected.');}
export function cohortFigure(w={}){let c=selectedCohort(w.antibiotic!==false,w.step||0),body='';for(let i=0;i<c.total;i++){let x=55+i%8*64,y=85+Math.floor(i/8)*48,r=i>=c.susceptible;body+=`<rect x="${x}" y="${y}" width="42" height="24" rx="12" fill="${r?'#e4b893':'#8eb9b4'}" ${r?'stroke="#f4ddad" stroke-width="4"':''}/>`+txt(x+21,y+18,r?'R':'S',17);}body+=txt(280,345,`S susceptible: ${c.susceptible} · R resistant: ${c.resistant}`,21)+txt(280,385,'Supplied counts · no real time scale',20);return frame(body,'Bacterial cohort. '+c.susceptible+' susceptible and '+c.resistant+' resistant.');}
export function doseFigure(selected=null){let body='<path d="M85 50V305H485" fill="none" stroke="#c4d2d0" stroke-width="2"/>';for(let v of[0,20,40,60,80,100])body+=txt(53,310-v*2.5,String(v),18)+`<path d="M85 ${305-v*2.5}H485" stroke="#718c92" stroke-width="1"/>`;for(let d of doseData)body+=txt(95+d.level*125,337,String(d.level),20);for(let[key,c]of[['benefit','#9bc6ba'],['harm','#eca792']]){body+=`<polyline points="${doseData.map(d=>`${95+d.level*125},${305-d[key]*2.5}`).join(' ')}" fill="none" stroke="${c}" stroke-width="4"/>`;for(let d of doseData)body+=`<circle cx="${95+d.level*125}" cy="${305-d[key]*2.5}" r="${d.level===Number(selected)&&selected!==null?8:4}" fill="${c}"/>`;}body+=txt(280,27,'Original trial observations / %',22)+txt(280,380,'Tested dose level · arbitrary units',21);return frame(body,'Dose levels0 to3; benefit0,30,65,70 percent; harm0,2,6,24 percent.')+'<p class="med-key">Benefit: green line · Harm: coral line</p>'+dataTable(['Level','Benefit / %','Harm / %'],doseData.map(d=>[d.level,d.benefit,d.harm]));}
export function dataTable(head,rows){return `<table class="med-data"><thead><tr>${head.map(x=>`<th scope="col">${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;}
export function medicineFigure(w={}){let kind=w.kind||'memory',s=w.state||'initial',r=w.revealed!==false,body='';if(kind==='network')return networkFigure(w);if(kind==='selection')return cohortFigure(w);if(kind==='dose')return doseFigure(w.level??null);if(kind==='screen')return frame(txt(280,65,'Compare efficacy with toxicity')+candidateData.map((d,i)=>{let y=125+i*90;return txt(70,y+10,d.id)+`<rect x="110" y="${y-20}" width="${d.effect*4}" height="18" fill="#9bc6ba"/><rect x="110" y="${y+5}" width="${d.harm*4}" height="18" fill="#eca792"/>`;}).join('')+txt(280,400,'Original effect/harm units · see table',20),'Screening evidence')+dataTable(['Candidate','Effect','Harm'],candidateData.map(d=>[d.id,d.effect,d.harm]));
if(kind==='memory'){let n=r?(s==='repeat'?7:s==='different'?1:3):1;body=s==='different'?'<rect x="250" y="65" width="60" height="60" fill="#9bbfb9"/>':'<circle cx="280" cy="95" r="35" fill="#9bbfb9"/>';for(let i=0;i<n;i++){let x=100+i%4*115,y=200+Math.floor(i/4)*80;body+=`<path d="M${x} ${y+40}V${y+15}l-20-20m20 20l20-20" stroke="#ecb19c" stroke-width="8" fill="none"/>`;}body+=txt(280,370,s==='repeat'?'Faster response to same antigen':s==='different'?'Different shape · match not established':'Initial response to this antigen',22);}
else if(kind==='sources'){let names={foxglove:['Foxglove','Digitalis'],willow:['Willow','Aspirin origins'],mould:['Penicillium','Penicillin · Fleming'],lab:['Pharmaceutical synthesis','Most new drugs']},n=names[s]||names.lab;body=txt(280,70,n[0]);if(s==='mould')body+='<circle cx="280" cy="210" r="100" fill="none" stroke="#b7cccc" stroke-width="5"/><circle cx="280" cy="210" r="40" fill="#a7b9a1"/>';else if(s==='lab')body+='<path d="M250 115v60l-65 100q95 55 190 0l-65-100v-60z" fill="#b7ceca" stroke="#e3d3b7" stroke-width="4"/>';else{body+='<path d="M280 300V125" stroke="#9db89e" stroke-width="6"/>';for(let i=0;i<5;i++)body+=`<ellipse cx="${i%2?250:310}" cy="${145+i*30}" rx="${s==='foxglove'?17:10}" ry="26" fill="${s==='foxglove'?'#c1a0b6':'#abc4aa'}"/>`;}body+=txt(280,365,r?n[1]:'Predict the source connection',22);}
else if(kind==='preclinical'){let n=s==='clinical'?3:s==='animals'?2:s==='tissues'?1:0,names=['Cells','Tissues','Live animals'];body=txt(280,55,'Preclinical laboratory evidence');for(let i=0;i<3;i++)body+=`<rect x="${30+i*180}" y="125" width="150" height="120" rx="18" fill="${n===i?'#789e9c':'#4c6875'}" stroke="#d1d4bf" stroke-width="2"/>`+txt(105+i*180,195,names[i],20);body+=txt(280,320,'Then: cautious trials in people',22)+txt(280,370,'Different models; human limits remain',20);}
else if(kind==='results'){body=txt(280,55,'Original parallel-group outcomes');for(let[i,n]of[65,40].entries())body+=`<rect x="${150+i*180}" y="${300-n*2.5}" width="90" height="${n*2.5}" fill="${i?'#d7b99e':'#9cc4b9'}"/>`+txt(195+i*180,330,i?'Placebo':'Drug',21)+txt(195+i*180,105+i*60,n+'/100',24);body+=txt(280,385,'Improvement counts · equal group sizes',20);}
else if(kind==='review'){body=txt(280,65,'Evidence → scrutiny → publication')+'<path d="M80 200H470l-25-15m25 15l-25 15" stroke="#d8cfb5" stroke-width="4"/>';for(let i=0;i<3;i++)body+=`<rect x="${45+i*185}" y="145" width="120" height="100" rx="15" fill="#698c91"/>`+txt(105+i*185,205,['Study','Review','Report'][i],20);body+=txt(280,340,'Scrutiny can find weaknesses',22)+txt(280,380,'Further evidence can change conclusions',20);}
else if(kind==='trial'){body=txt(280,65,'Two coded comparison groups');for(let i=0;i<20;i++){let x=70+(i%5)*105,y=125+Math.floor(i/5)*45;body+=`<circle cx="${x}" cy="${y}" r="12" fill="${i<10?'#9bbfb8':'#d4b398'}"/>`;}body+=txt(280,340,'Random allocation; same outcome measure',20)+txt(280,380,'Drug / placebo codes concealed',20);}
else if(kind==='host'||(kind==='treatment'&&s==='viral')){body='<ellipse cx="280" cy="200" rx="160" ry="115" fill="#7e9f9f" fill-opacity=".3" stroke="#bfd2cc" stroke-width="4"/><ellipse cx="200" cy="240" rx="30" ry="24" fill="#b09db0"/>';let n=kind==='host'&&s==='target'&&r?1:6;for(let i=0;i<n;i++){let x=240+(i%3)*60,y=155+Math.floor(i/3)*70;body+=`<circle cx="${x}" cy="${y}" r="14" fill="#dfaa98" stroke="#f1cfae" stroke-width="4"/><path d="M${x-22} ${y}h44m-22-22v44" stroke="#f1cfae" stroke-width="2"/>`;}if(s==='damage'&&r)body+='<path d="M130 125L425 285M130 285L425 125" stroke="#edaa94" stroke-width="5"/>';body+=txt(280,55,'Viruses inside a host cell',22)+txt(280,355,s==='damage'?'Host damage is a toxicity concern':kind==='treatment'?'Antibiotic does not kill the virus':'Aim: selective effect on virus activity',21);}
else{let count=kind==='susceptibility'?(r&&s==='effective'?0:6):s==='bacterial'&&r?0:6;for(let i=0;i<count;i++)body+=`<rect x="${120+(i%3)*120}" y="${125+Math.floor(i/3)*80}" width="75" height="28" rx="14" fill="#94beb8"/>`;body+=txt(280,70,kind==='host'?'Inside a host cell':'Pathogen comparison');body+=txt(280,345,s==='pain'?'Pain reduced; pathogen remains':s==='viral'?'Antibiotic does not kill the virus':kind==='host'?'Viral processes share a host-cell setting':count?'Organisms remain in this comparison':'Susceptible bacteria reduced',21);}
return frame(body,w.title||'Medicine mechanism')+'<p class="diagram-caption">'+esc(w.result||'Symbolic colours, counts and stages')+'</p>';}
